import{_ as p,r as s,o,c,e as a,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"任务调度 - October CMS - 3.x","titleTemplate":false,"description":"执行几乎任何事情的计划任务。","frontmatter":{"subtitle":"执行几乎任何事情的计划任务。"},"headers":[{"level":2,"title":"定义调度","slug":"定义调度","link":"#定义调度","children":[{"level":3,"title":"调度频率选项","slug":"调度频率选项","link":"#调度频率选项","children":[{"level":4,"title":"条件测试约束","slug":"条件测试约束","link":"#条件测试约束","children":[]}]},{"level":3,"title":"防止任务重叠","slug":"防止任务重叠","link":"#防止任务重叠","children":[]}]},{"level":2,"title":"任务输出","slug":"任务输出","link":"#任务输出","children":[]},{"level":2,"title":"任务钩子","slug":"任务钩子","link":"#任务钩子","children":[{"level":4,"title":"Ping URL","slug":"ping-url","link":"#ping-url","children":[]}]}],"relativePath":"3.x/zh-cn/extend/system/scheduling.md","filePath":"3.x/zh-cn/extend/system/scheduling.md"}'),d={name:"3.x/zh-cn/extend/system/scheduling.md"};function i(r,n,k,g,h,f){const t=s("pre-heading"),e=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"任务调度",-1)),a(e),n[1]||(n[1]=u(`<div class="custom-block aside"><p>有关如何设置调度器任务的说明，请参阅<a href="./../../setup/installation.html">安装指南</a>。</p></div><p>过去，开发者需要为每个需要调度的任务生成一个 Cron 条目。然而，这有时会很令人头疼。你的任务调度不再在源代码控制中，你必须通过 SSH 连接到服务器来添加 Cron 条目。命令调度器允许你在应用程序本身中流畅且富有表现力地定义命令调度，并且服务器上只需要一个 Cron 条目。</p><p><a id="oc-defining-schedules"></a></p><h2 id="定义调度"><a href="#定义调度" class="header-anchor">#</a> 定义调度</h2><p>你可以通过在<a href="./../extending.html">插件注册文件</a>中覆盖 <code>registerSchedule</code> 方法来定义所有计划任务。该方法将接受一个 <code>$schedule</code> 参数，用于定义命令及其执行频率。</p><p>让我们从一个调度任务的示例开始。在此示例中，我们将调度一个 <code>Closure</code> 在每天午夜被调用。在 <code>Closure</code> 中，我们将执行一个数据库查询来清空一个表：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSchedule</span><span class="token punctuation">(</span><span class="token variable">$schedule</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;recent_users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>除了调度 <code>Closure</code> 调用外，你还可以调度<a href="./../console-commands.html">控制台命令</a>和操作系统命令。例如，你可以使用 <code>command</code> 方法调度控制台命令：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cache:clear&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>exec</code> 命令可用于向操作系统发出命令：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">exec</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;node /home/acme/script.js&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="调度频率选项"><a href="#调度频率选项" class="header-anchor">#</a> 调度频率选项</h3><p>当然，你可以为任务分配多种调度频率：</p><div class="table"><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td><code>-&gt;cron(&#39;* * * * *&#39;);</code></td><td>按自定义 Cron 调度运行任务</td></tr><tr><td><code>-&gt;everyMinute();</code></td><td>每分钟运行任务</td></tr><tr><td><code>-&gt;everyFiveMinutes();</code></td><td>每五分钟运行任务</td></tr><tr><td><code>-&gt;everyTenMinutes();</code></td><td>每十分钟运行任务</td></tr><tr><td><code>-&gt;everyThirtyMinutes();</code></td><td>每三十分钟运行任务</td></tr><tr><td><code>-&gt;hourly();</code></td><td>每小时运行任务</td></tr><tr><td><code>-&gt;daily();</code></td><td>每天午夜运行任务</td></tr><tr><td><code>-&gt;dailyAt(&#39;13:00&#39;);</code></td><td>每天 13:00 运行任务</td></tr><tr><td><code>-&gt;twiceDaily(1, 13);</code></td><td>每天 1:00 和 13:00 运行任务</td></tr><tr><td><code>-&gt;weekly();</code></td><td>每周运行任务</td></tr><tr><td><code>-&gt;monthly();</code></td><td>每月运行任务</td></tr></tbody></table></div><p>这些方法可以与附加约束组合使用，以创建更精细调整的调度，仅在一周中的特定日子运行。例如，调度一个命令在每周一运行：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Runs once a week on Monday at 13:00...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">weekly</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">mondays</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">at</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;13:00&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>以下是附加调度约束的列表：</p><div class="table"><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td><code>-&gt;weekdays();</code></td><td>将任务限制在工作日</td></tr><tr><td><code>-&gt;sundays();</code></td><td>将任务限制在周日</td></tr><tr><td><code>-&gt;mondays();</code></td><td>将任务限制在周一</td></tr><tr><td><code>-&gt;tuesdays();</code></td><td>将任务限制在周二</td></tr><tr><td><code>-&gt;wednesdays();</code></td><td>将任务限制在周三</td></tr><tr><td><code>-&gt;thursdays();</code></td><td>将任务限制在周四</td></tr><tr><td><code>-&gt;fridays();</code></td><td>将任务限制在周五</td></tr><tr><td><code>-&gt;saturdays();</code></td><td>将任务限制在周六</td></tr><tr><td><code>-&gt;when(Closure);</code></td><td>基于条件测试限制任务</td></tr></tbody></table></div><h4 id="条件测试约束"><a href="#条件测试约束" class="header-anchor">#</a> 条件测试约束</h4><p><code>when</code> 方法可用于根据给定条件测试的结果来限制任务的执行。换句话说，如果给定的 <code>Closure</code> 返回 <code>true</code>，则只要没有其他约束条件阻止任务运行，任务就会执行：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">when</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="防止任务重叠"><a href="#防止任务重叠" class="header-anchor">#</a> 防止任务重叠</h3><p>默认情况下，即使前一个任务实例仍在运行，计划任务也会运行。要防止这种情况，你可以使用 <code>withoutOverlapping</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withoutOverlapping</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在此示例中，<code>emails:send</code> 控制台命令将每分钟运行，如果它尚未运行的话。<code>withoutOverlapping</code> 方法在你有执行时间差异很大的任务时特别有用，可以防止你需要精确预测给定任务将花费多长时间。</p><h2 id="任务输出"><a href="#任务输出" class="header-anchor">#</a> 任务输出</h2><p>调度器提供了几种便捷的方法来处理计划任务生成的输出。首先，使用 <code>sendOutputTo</code> 方法，你可以将输出发送到文件以供后续检查。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">sendOutputTo</span><span class="token punctuation">(</span><span class="token variable">$filePath</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>使用 <code>emailOutputTo</code> 方法，你可以将输出通过电子邮件发送到你选择的电子邮件地址。请注意，输出必须首先使用 <code>sendOutputTo</code> 方法发送到文件。此外，在通过电子邮件发送任务输出之前，你应该配置<a href="./../../setup/mail-config.html">邮件服务</a>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">sendOutputTo</span><span class="token punctuation">(</span><span class="token variable">$filePath</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">emailOutputTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo@example.tld&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p><code>emailOutputTo</code> 和 <code>sendOutputTo</code> 方法仅适用于 <code>command</code> 方法，不支持 <code>call</code>。</p></div><h2 id="任务钩子"><a href="#任务钩子" class="header-anchor">#</a> 任务钩子</h2><p>使用 <code>before</code> 和 <code>after</code> 方法，你可以指定在计划任务完成前后执行的代码：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">before</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Task is about to start...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">after</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Task is complete...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="ping-url"><a href="#ping-url" class="header-anchor">#</a> Ping URL</h4><p>使用 <code>pingBefore</code> 和 <code>thenPing</code> 方法，调度器可以在任务完成前后自动 ping 给定的 URL。此方法对于通知外部服务你的计划任务正在开始或已完成很有用：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">pingBefore</span><span class="token punctuation">(</span><span class="token variable">$url</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">thenPing</span><span class="token punctuation">(</span><span class="token variable">$url</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,37))])}const y=p(d,[["render",i]]);export{v as __pageData,y as default};
